  --color-danger-subtle: #7f1d1d;
  --color-info-base: #7dd3fc;
  --color-info-subtle: #082f49;

  /* Spacing Scale */
  --spacing-0: 0px;
  --spacing-1: 4px;
  --spacing-2: 8px;
  --spacing-3: 12px;
  --spacing-4: 16px;
  --spacing-5: 20px;
  --spacing-6: 24px;
  --spacing-8: 32px;
  --spacing-10: 40px;
  --spacing-12: 48px;

  /* Radii Scale */
  --radius-xs: 2px;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-full: 9999px;

  /* Typography */
  --typography-font-sans: 'JetBrains Mono', 'Fira Code', ui-monospace, Menlo, Consolas, monospace;
  --typography-font-mono: 'JetBrains Mono', 'Fira Code', ui-monospace, Menlo, Consolas, monospace;
  --typography-size-xs: 0.75rem;
